SELECT f.feed_id, f.feed_img_url, COUNT(l.like_id) AS likeCount, FROM feed_tb f LEFT JOIN like_tb l ON f.feed_id = l.feed_id
f.feed_id < #{cursorFeedId}
AND f.user_id = #{userId}
GROUP BY f.feed_id ORDER BY f.feed_id DESC LIMIT #{size}

